use super::*;

// Independently stated server INFO config fixtures, not generated by resources().
fn fixture(name: &str, replicas: usize) -> Value {
    let (subjects, size, history, discard, rollup) = match name {
        "CHAT" => (
            json!([
                "epochgrid.v1.group.*.handshake",
                "epochgrid.v1.group.*.message"
            ]),
            65536,
            -1,
            "old",
            false,
        ),
        "MAILBOX" => (
            json!(["epochgrid.v1.user.*.*.inbox"]),
            65536,
            -1,
            "old",
            false,
        ),
        "KV_IDENTITIES" => (json!(["$KV.IDENTITIES.>"]), -1, 1, "new", true),
        "KV_CHANNELS" => (json!(["$KV.CHANNELS.>"]), -1, 1, "new", true),
        "KV_TRANSPARENCY" => (json!(["$KV.TRANSPARENCY.>"]), 65536, 1, "new", true),
        _ => panic!("unexpected fixture"),
    };
    json!({"name":name, "subjects":subjects, "storage":"file", "retention":"limits",
        "num_replicas":replicas, "max_msg_size":size, "max_msgs_per_subject":history,
        "discard":discard, "allow_rollup_hdrs":rollup, "deny_delete":rollup,
        "allow_direct":rollup, "max_bytes":-1, "max_msgs":-1, "max_consumers":-1})
}

const NAMES: [&str; 5] = [
    "CHAT",
    "MAILBOX",
    "KV_IDENTITIES",
    "KV_CHANNELS",
    "KV_TRANSPARENCY",
];

#[test]
fn manifest_is_versioned_strict_and_roundtrips() -> Result<()> {
    for replicas in [1, 3] {
        let manifest = DeploymentManifest::new(replicas)?;
        assert_eq!(manifest.replicas(), replicas);
        assert_eq!(
            serde_json::from_value::<DeploymentManifest>(json!({"version":1,"replicas":replicas}))?,
            manifest
        );
        assert_eq!(
            serde_json::from_str::<DeploymentManifest>(&serde_json::to_string(&manifest)?)?,
            manifest
        );
    }
    for value in [
        json!({}),
        json!({"version":2,"replicas":1}),
        json!({"version":1,"replicas":2}),
        json!({"version":1,"replicas":0}),
        json!({"version":1,"replicas":3,"typo":true}),
        json!({"version":1,"replicas":-1}),
    ] {
        assert!(serde_json::from_value::<DeploymentManifest>(value).is_err());
    }
    for replicas in [0, 2, 4, 5, usize::MAX] {
        assert!(DeploymentManifest::new(replicas).is_err());
    }
    assert!(
        serde_json::from_str::<DeploymentManifest>(r#"{"version":1,"replicas":1,"replicas":3}"#)
            .is_err()
    );
    Ok(())
}

#[test]
fn generated_artifacts_match_independent_contract() -> Result<()> {
    for replicas in [1, 3] {
        let manifest = DeploymentManifest::new(replicas)?;
        let artifacts = manifest.artifacts()?;
        assert_eq!(artifacts.len(), 6);
        assert_eq!(artifacts, manifest.artifacts()?);
        assert_eq!(
            serde_json::from_str::<DeploymentManifest>(&artifacts[MANIFEST_FILE])?,
            manifest
        );
        for name in NAMES {
            let mut generated: Config = serde_json::from_str(&artifacts[&format!("{name}.json")])?;
            let mut independent: Config = serde_json::from_value(fixture(name, replicas))?;
            generated.subjects.sort();
            independent.subjects.sort();
            assert_eq!(generated, independent, "{name}");
            assert!(manifest.compare(name, &independent)?.is_empty());
        }
    }
    Ok(())
}

#[test]
fn incompatible_fields_are_reported_individually() -> Result<()> {
    let manifest = DeploymentManifest::new(3)?;
    let changes = [
        ("name", json!("OTHER"), "name"),
        ("subjects", json!([">"]), "subjects"),
        ("storage", json!("memory"), "storage"),
        ("retention", json!("interest"), "retention"),
        ("retention", json!("workqueue"), "retention"),
        ("num_replicas", json!(1), "num_replicas"),
        ("num_replicas", json!(0), "num_replicas"),
        ("max_age", json!(1), "max_age"),
        ("no_ack", json!(true), "no_ack"),
        ("persist_mode", json!("async"), "persist_mode"),
        ("sealed", json!(true), "sealed"),
        ("template_owner", json!("managed"), "template_owner"),
        (
            "discard_new_per_subject",
            json!(true),
            "discard_new_per_subject",
        ),
        ("mirror", json!({"name":"OTHER"}), "mirror"),
        ("sources", json!([{"name":"OTHER"}]), "sources"),
        ("mirror_direct", json!(true), "mirror_direct"),
        (
            "subject_transform",
            json!({"src":">","dest":"other.>"}),
            "subject_transform",
        ),
        (
            "republish",
            json!({"src":">","dest":"other.>"}),
            "republish",
        ),
        ("allow_msg_ttl", json!(true), "allow_message_ttl"),
        (
            "subject_delete_marker_ttl",
            json!(1000),
            "subject_delete_marker_ttl",
        ),
        ("pause_until", json!("2099-01-01T00:00:00Z"), "pause_until"),
        (
            "allow_msg_schedules",
            json!(true),
            "allow_message_schedules",
        ),
        ("allow_msg_counter", json!(true), "allow_message_counter"),
        (
            "consumer_limits",
            json!({"inactive_threshold":1000,"max_ack_pending":1}),
            "consumer_limits",
        ),
        ("max_bytes", json!(-2), "max_bytes"),
    ];
    for name in NAMES {
        for (field, value, diagnostic) in &changes {
            let mut config = fixture(name, 3);
            config[*field] = value.clone();
            let issues = manifest.compare(name, &serde_json::from_value(config)?)?;
            assert_eq!(issues.len(), 1, "{name}/{field}: {issues:?}");
            assert_eq!(issues[0].field, *diagnostic);
        }
        for (field, value) in [
            ("max_msg_size", json!(32768)),
            ("max_msgs_per_subject", json!(2)),
            ("allow_rollup_hdrs", json!(!name.starts_with("KV_"))),
            (
                "discard",
                json!(if name.starts_with("KV_") {
                    "old"
                } else {
                    "new"
                }),
            ),
        ] {
            let mut config = fixture(name, 3);
            config[field] = value;
            assert_eq!(
                manifest
                    .compare(name, &serde_json::from_value(config)?)?
                    .len(),
                1,
                "{name}/{field}"
            );
        }
    }
    for name in &NAMES[2..] {
        for (field, value) in [
            ("deny_delete", false),
            ("deny_purge", true),
            ("allow_direct", false),
        ] {
            let mut config = fixture(name, 3);
            config[field] = json!(value);
            assert_eq!(
                manifest
                    .compare(name, &serde_json::from_value(config)?)?
                    .len(),
                1
            );
        }
    }
    Ok(())
}

#[test]
fn operator_budgets_and_unrelated_settings_are_preserved() -> Result<()> {
    let manifest = DeploymentManifest::new(1)?;
    for name in NAMES {
        let mut config = fixture(name, 1);
        for (field, value) in [
            ("max_bytes", json!(100000000)),
            ("max_msgs", json!(100000)),
            ("max_consumers", json!(100)),
            ("description", json!("Operator managed")),
            ("metadata", json!({"owner":"operations"})),
            ("placement", json!({"cluster":"production","tags":["ssd"]})),
            ("compression", json!("s2")),
            ("persist_mode", json!("default")),
            ("duplicate_window", json!(120000000000u64)),
            ("sources", json!([])),
            (
                "consumer_limits",
                json!({"inactive_threshold":0,"max_ack_pending":100}),
            ),
        ] {
            config[field] = value;
        }
        let observed: Config = serde_json::from_value(config)?;
        let before = observed.clone();
        assert!(manifest.compare(name, &observed)?.is_empty(), "{name}");
        assert_eq!(observed, before);
    }
    for size in [-1, 0, 65536, 131072] {
        let mut config = fixture("KV_IDENTITIES", 1);
        config["max_msg_size"] = json!(size);
        assert!(
            manifest
                .compare("KV_IDENTITIES", &serde_json::from_value(config)?)?
                .is_empty()
        );
    }
    assert!(manifest.compare("UNKNOWN", &Config::default()).is_err());
    Ok(())
}

#[test]
fn duplicate_subjects_and_multiple_failures_are_not_hidden() -> Result<()> {
    let manifest = DeploymentManifest::new(3)?;
    let mut config: Config = serde_json::from_value(fixture("MAILBOX", 1))?;
    config.subjects.push(config.subjects[0].clone());
    config.max_age = std::time::Duration::from_secs(1);
    let issues = manifest.compare("MAILBOX", &config)?;
    assert_eq!(issues.len(), 3);
    assert_eq!(
        serde_json::from_str::<Vec<ResourceMismatch>>(&serde_json::to_string(&issues)?)?,
        issues
    );
    Ok(())
}

#[test]
fn bounded_contract_preserves_v1_and_enforces_finite_budgets() -> Result<()> {
    let legacy = DeploymentManifest::new(3)?;
    assert_eq!(legacy.resources()[0].max_bytes, -1);
    assert_eq!(legacy.resources()[0].discard, DiscardPolicy::Old);
    let bounded = DeploymentManifest::bounded(3, crate::capacity::Capacity::default())?;
    let value = serde_json::to_value(&bounded)?;
    assert_eq!(value["version"], 2);
    let restored: DeploymentManifest = serde_json::from_value(value)?;
    assert_eq!(restored, bounded);
    for mut resource in bounded.resources() {
        assert!(resource.max_bytes >= 262144);
        assert!(resource.max_consumers > 0);
        assert_eq!(resource.discard, DiscardPolicy::New);
        assert!(bounded.compare(&resource.name, &resource)?.is_empty());
        resource.max_bytes = -1;
        assert!(
            bounded
                .compare(&resource.name, &resource)?
                .iter()
                .any(|m| m.field == "max_bytes")
        );
    }
    assert!(serde_json::from_str::<DeploymentManifest>(r#"{"version":2,"replicas":1}"#).is_err());
    Ok(())
}
